const fs = require('fs');
const path = require('path');

const file = process.argv[2];

// Robust CSV parser: handles quotes, escaped quotes, and newlines inside quoted fields
function parseCSV(text) {
  const rows = [];
  let row = [];
  let field = '';
  let inQuotes = false;
  let i = 0;
  const n = text.length;
  while (i < n) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i += 2; continue; }
        inQuotes = false; i++; continue;
      }
      field += c; i++; continue;
    }
    if (c === '"') { inQuotes = true; i++; continue; }
    if (c === ',') { row.push(field); field = ''; i++; continue; }
    if (c === '\n') { row.push(field); field = ''; rows.push(row); row = []; i++; continue; }
    if (c === '\r') { i++; continue; }
    field += c; i++;
  }
  if (field.length > 0 || row.length > 0) { row.push(field); rows.push(row); }
  return rows;
}

const text = fs.readFileSync(file, 'utf8');
const rows = parseCSV(text);
const header = rows[0];
const data = rows.slice(1);
console.log('HEADER:', JSON.stringify(header));
console.log('TOTAL DATA ROWS (parsed):', data.length);

// Assemble records from the discovered columns
const idCol = header.indexOf('airbnb_listing_id');
const dateCol = header.indexOf('date');
const priceCol = header.indexOf('price');
const aqCol = header.indexOf('aquisition_date');

const byIdDate = new Map();
const distinctIds = new Set();
const distinctDates = new Set();
let malformed = 0;
let counts = {};

for (const r of data) {
  if (r.length !== header.length) { malformed++; }
  const id = r[idCol];
  const d = r[dateCol];
  const p = r[priceCol];
  if (id === undefined || d === undefined || p === undefined) { malformed++; continue; }
  const cleanId = id.replace(/"/g, '');
  const cleanD = d.replace(/"/g, '');
  const key = cleanId + '|' + cleanD;
  byIdDate.set(key, (byIdDate.get(key) || 0) + 1);
  distinctIds.add(cleanId);
  distinctDates.add(cleanD);
  const m = /^\s*"?(-?\d+(?:\.\d+)?)"?\s*$/.exec(p);
  const pv = m ? parseFloat(m[1]) : NaN;
  if (isNaN(pv)) { counts['non_numeric_price'] = (counts['non_numeric_price']||0)+1; }
  else { counts['numeric_price'] = (counts['numeric_price']||0)+1; }
  if (distinctDates.size <= 0) {}
}

let realDup = 0;
for (const [k, v] of byIdDate) { if (v > 1) realDup++; }

let minDate = null, maxDate = null;
for (const d of distinctDates) {
  if (minDate === null || d < minDate) minDate = d;
  if (maxDate === null || d > maxDate) maxDate = d;
}

const dateList = Array.from(distinctDates).sort();
const dateCount = {};
for (const d of dateList) { dateCount[d.slice(0,7)] = (dateCount[d.slice(0,7)]||0)+1; }

console.log('DISTINCT LISTING IDS:', distinctIds.size);
console.log('DISTINCT DATES:', distinctDates.size);
console.log('MIN DATE:', minDate, 'MAX DATE:', maxDate);
console.log('DATES BY MONTH:', JSON.stringify(dateCount, null, 0));
console.log('REAL DUP (id,date) PAIRS:', realDup);
console.log('MALFORMED COLUMN-COUNT ROWS:', malformed);
console.log('PRICE COUNTS:', JSON.stringify(counts));
console.log('SAMPLE OF DISTINCT DATES (first 15):', dateList.slice(0,15).join(', '));
console.log('SAMPLE OF DISTINCT DATES (last 15):', dateList.slice(-15).join(', '));

const fs = require('fs');

const file = process.argv[2];
function parseCSV(text) {
  const rows = []; let row=[]; let field=''; let inQuotes=false; let i=0; const n=text.length;
  while(i<n){ const c=text[i];
    if(inQuotes){ if(c==='"'){ if(text[i+1]==='"'){field+='"';i+=2;continue;} inQuotes=false;i++;continue;} field+=c;i++;continue;}
    if(c==='"'){inQuotes=true;i++;continue;}
    if(c===','){row.push(field);field='';i++;continue;}
    if(c==='\n'){row.push(field);field='';rows.push(row);row=[];i++;continue;}
    if(c==='\r'){i++;continue;}
    field+=c;i++;
  }
  if(field.length>0||row.length>0){row.push(field);rows.push(row);}
  return rows;
}
const rows = parseCSV(fs.readFileSync(file,'utf8'));
const header = rows[0];
const idCol=header.indexOf('airbnb_listing_id'), dateCol=header.indexOf('date'),
      priceCol=header.indexOf('price'), aqCol=header.indexOf('aquisition_date');
const data = rows.slice(1);
const clean = r => (r===undefined?undefined:String(r).replace(/^"|"$/g,''));
// Map from id|date -> list of {price, aq}
const groups = new Map();
for(const r of data){
  const id=clean(r[idCol]), d=clean(r[dateCol]), p=clean(r[priceCol]), aq=clean(r[aqCol]);
  const key=id+'|'+d;
  if(!groups.has(key)) groups.set(key,[]);
  groups.get(key).push({p, aq});
}
// Inspect duplicate groups
let dupGroups=0;
const examples=[];
for(const [k,v] of groups){ if(v.length>1){ dupGroups++; if(examples.length<8 && v.length>1){ 
  const idset=new Set(v.map(x=>x.aq));
  examples.push({key:k, count:v.length, distinctAq:idset.size, entries:v.slice(0,6)});
}}}
console.log('TOTAL (id,date) GROUPS:', groups.size);
console.log('GROUPS WITH >1 ROW (duplicates):', dupGroups);
console.log('\nEXAMPLES of duplicate rows:');
const seenP=new Set();
for(const ex of examples){
  const sig = ex.entries.map(e=>e.p+'@'+e.aq).join('|');
  console.log(JSON.stringify(ex));
}
// Check: are duplicate rows identical (same price & aquisition) or different (different aquisition captures)?
let fullyIdentical=0, diffCapture=0, diffPriceSameCapture=0; 
for(const [k,v] of groups){
  if(v.length<=1) continue;
  const priceSet=new Set(v.map(x=>x.p));
  const aqSet=new Set(v.map(x=>x.aq));
  if(priceSet.size===1 && aqSet.size===1) fullyIdentical++;
  else if(priceSet.size>1 && aqSet.size===1) diffPriceSameCapture++;
  else if(aqSet.size>1) diffCapture++;
}
console.log('\nduplicate groups where rows are IDENTICAL (same price+same capture):', fullyIdentical);
console.log('duplicate groups with DIFFERENT price but SAME capture:', diffPriceSameCapture);
console.log('duplicate groups with DIFFERENT capture date (multiple snapshots):', diffCapture);

const fs = require('fs');
const file = process.argv[2];
function parseCSV(text){const rows=[];let row=[];let field='';let inQ=false;let i=0;const n=text.length;while(i<n){const c=text[i];if(inQ){if(c==='"'){if(text[i+1]==='"'){field+='"';i+=2;continue;}inQ=false;i++;continue;}field+=c;i++;continue;}if(c==='"'){inQ=true;i++;continue;}if(c===','){row.push(field);field='';i++;continue;}if(c==='\n'){row.push(field);field='';rows.push(row);row=[];i++;continue;}if(c==='\r'){i++;continue;}field+=c;i++;}if(field.length>0||row.length>0){row.push(field);rows.push(row);}return rows;}
const rows=parseCSV(fs.readFileSync(file,'utf8'));
const header=rows[0];
const dateCol=header.indexOf('date'), aqCol=header.indexOf('aquisition_date'), idCol=header.indexOf('airbnb_listing_id'), priceCol=header.indexOf('price');
const data=rows.slice(1);
const clean=r=>r===undefined?undefined:String(r).replace(/^"|"$/g,'');

// Distinct capture dates (aquisition_date by date-only)
const captureDates = new Set();
for(const r of data){ captureDates.add(clean(r[aqCol])); }
const aqList = Array.from(captureDates).map(aq=>{const d=aq.slice(0,10)+' '+aq.slice(11,19);return d;});
const aqByDay = new Map();
for(const aq of aqList){ aqByDay.set(aq.slice(0,10),(aqByDay.get(aq.slice(0,10))||0)+1); }
console.log('NUM DISTINCT AQUISITION_TIMESTAMPS:', aqList.length);
console.log('DISTINCT AQUISITION DAYS:', aqByDay.size);
console.log('AQUISITION DAYS:', JSON.stringify(Array.from(aqByDay.keys()).sort()));
console.log('AQUISITION COUNTS BY DAY:', JSON.stringify(Object.fromEntries(Array.from(aqByDay.entries()).sort())));

// Per listing, how many distinct capture days appear?
const idCaptures = new Map();
for(const r of data){ const id=clean(r[idCol]); const day=clean(r[aqCol]).slice(0,10); if(!idCaptures.has(id)) idCaptures.set(id,new Set()); idCaptures.get(id).add(day); }
const capDist = new Map();
for(const [id,set] of idCaptures){ capDist.set(set.size,(capDist.get(set.size)||0)+1); }
console.log('\nListings by number of capture days:');
console.log(JSON.stringify(Object.fromEntries(Array.from(capDist.entries()).sort((a,b)=>a[0]-b[0]))));

// Distribution of rows per capture day
const rowsPerDay = new Map();
for(const r of data){ const day=clean(r[aqCol]).slice(0,10); rowsPerDay.set(day,(rowsPerDay.get(day)||0)+1); }
console.log('\nROWS PER AQUISITION DAY:');
for(const [d,c] of Array.from(rowsPerDay.entries()).sort()){ console.log(d, c); }

const fs = require('fs');
const file = process.argv[2];
function parseCSV(text){const rows=[];let row=[];let field='';let inQ=false;let i=0;const n=text.length;while(i<n){const c=text[i];if(inQ){if(c==='"'){if(text[i+1]==='"'){field+='"';i+=2;continue;}inQ=false;i++;continue;}field+=c;i++;continue;}if(c==='"'){inQ=true;i++;continue;}if(c===','){row.push(field);field='';i++;continue;}if(c==='\n'){row.push(field);field='';rows.push(row);row=[];i++;continue;}if(c==='\r'){i++;continue;}field+=c;i++;}if(field.length>0||row.length>0){row.push(field);rows.push(row);}return rows;}
const rows=parseCSV(fs.readFileSync(file,'utf8'));
const header=rows[0];
const dateCol=header.indexOf('date'), aqCol=header.indexOf('aquisition_date'), idCol=header.indexOf('airbnb_listing_id'), priceCol=header.indexOf('price');
const data=rows.slice(1);
const clean=r=>r===undefined?undefined:String(r).replace(/^"|"$/g,'');

// group rows per aquisition day
const snap = {};
for(const r of data){
  const day = clean(r[aqCol]).slice(0,10);
  if(!snap[day]) snap[day] = { rows:0, ids:new Set(), dates:new Set() };
  snap[day].rows++;
  snap[day].ids.add(clean(r[idCol]));
  snap[day].dates.add(clean(r[dateCol]));
}
console.log('=== PER AQUISITION DATE ===');
for(const day of Object.keys(snap).sort()){
  const s = snap[day];
  const dates = Array.from(s.dates).sort();
  console.log(`\nDAY ${day}:`);
  console.log(`  rows=${s.rows}, unique listings=${s.ids.size}, unique stay-dates=${s.dates.size}`);
  console.log(`  date range: ${dates[0]} .. ${dates[dates.length-1]}`);
}

// Listings in ANY snapshot
const allIds = new Set();
for(const r of data){ allIds.add(clean(r[idCol])); }
console.log('\nTOTAL UNIQUE LISTINGS across ALL snapshots:', allIds.size);

// For a single clean measure: how many listings in the FULL (id,date) grid spanning 2025-01-06..2025-04-20?
// Count distinct (id) that appear in each snapshot AND overall distinct dates
const overallDates = new Set();
for(const r of data){ overallDates.add(clean(r[dateCol])); }
console.log('TOTAL DISTINCT STAY-DATES across all snapshots:', overallDates.size);

// Per snapshot: listings that appear in every snapshot? overlap between snapshots
const snapIds = Object.fromEntries(Object.keys(snap).map(d=>[d, snap[d].ids]));
const snapKeys = Object.keys(snap).sort();
for(let a=0;a<snapKeys.length;a++){
  for(let b=a+1;b<snapKeys.length;b++){
    const inter = new Set([...snapIds[snapKeys[a]]].filter(x=>snapIds[snapKeys[b]].has(x)));
    console.log(`overlap listings ${snapKeys[a]} & ${snapKeys[b]}: ${inter.size}`);
  }
}

