'use strict';

/**
 * Cruza o price_consolidated.csv (snapshot 2025-01-20) com os dados de
 * localização (Mesh_Ids) e características (Details) para caracterizar
 * bairros e perfis de imóvel.
 *
 * Métricas por grupo: n (imóveis), média, mediana, P22, P75 do avg_daily_price.
 *
 * Considerações:
 *  - Não assumimos que number_of_bedrooms=0 significa "studio": os anúncios
 *    com 0 quartos são heterogêneos (casas, suítes, hostels e registros sem
 *    quarto declarado). Por isso usamos a label neutra "0 quartos".
 *  - Relatamos quantos dos 514 imóveis consolidados são encontrados em cada
 *    fonte e a perda de join.
 */

const path = require('path');
const { readCSV, writeCSV, escCSV } = require('./lib/csv');

const DATA_DIR = path.join(__dirname, '..', 'data');
const OUT_DIR = path.join(__dirname, 'output');

function percentile(sorted, p) {
  if (sorted.length === 0) return null;
  const idx = (p / 100) * (sorted.length - 1);
  const lo = Math.floor(idx);
  const hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
}

function summarize(items, valueFn) {
  const vals = items.map(valueFn).filter((v) => v !== null && !isNaN(v)).sort((a, b) => a - b);
  const n = items.length;
  const mean = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
  return {
    n,
    mean: mean === null ? null : +mean.toFixed(2),
    median: vals.length ? +percentile(vals, 50).toFixed(2) : null,
    p22: vals.length ? +percentile(vals, 22).toFixed(2) : null,
    p75: vals.length ? +percentile(vals, 75).toFixed(2) : null,
  };
}

function main() {
  const consolidated = readCSV(path.join(OUT_DIR, 'price_consolidated.csv'));
  const mesh = readCSV(path.join(DATA_DIR, 'Mesh_Ids_Data_Itapema.csv'));
  const details = readCSV(path.join(DATA_DIR, 'Details_Itapema.csv'));

  console.log('Consolidado (preços):', consolidated.length, 'imóveis');
  console.log('Mesh (localização):', mesh.length, '| Details (características):', details.length);

  // ---- Join ----
  const meshById = new Map(mesh.map((r) => [r.airbnb_listing_id, r]));
  const detailsById = new Map(details.map((r) => [r.airbnb_listing_id, r]));

  const joined = [];
  let inMesh = 0, inDetails = 0, inBoth = 0;
  for (const rec of consolidated) {
    const m = meshById.get(rec.airbnb_listing_id);
    const d = detailsById.get(rec.airbnb_listing_id);
    if (m) inMesh++;
    if (d) inDetails++;
    if (m && d) inBoth++;
    joined.push({
      ...rec,
      suburb: m ? String(m.suburb).trim() : null,
      listing_type: d ? String(d.listing_type).trim() : null,
      n_bedrooms: d ? d.number_of_bedrooms : null,
    });
  }

  console.log(`\n=== EVENTOS DE JOIN (dos ${consolidated.length} consolidados) ===`);
  console.log(`Em Mesh (localização): ${inMesh}`);
  console.log(`Em Details (características): ${inDetails}`);
  console.log(`Em ambos (Mesh+Details): ${inBoth}`);
  console.log(`Perdidos (nem Mesh nem Details): ${consolidated.length - inBoth}`);

  // ---- Função de agregação e dashboard ----
  const groups = {
    suburb: {},
    listing_type: {},
    n_bedrooms: {},
  };
  for (const rec of joined) {
    if (rec.suburb) groups.suburb[rec.suburb] = groups.suburb[rec.suburb] || [];
    if (rec.suburb) groups.suburb[rec.suburb].push(rec);
    if (rec.listing_type) groups.listing_type[rec.listing_type] = groups.listing_type[rec.listing_type] || [];
    if (rec.listing_type) groups.listing_type[rec.listing_type].push(rec);
    if (rec.n_bedrooms !== null && rec.n_bedrooms !== '') {
      const key = rec.n_bedrooms === '0' ? '0 quartos' : rec.n_bedrooms + ' quarto(s)';
      groups.n_bedrooms[key] = groups.n_bedrooms[key] || [];
      groups.n_bedrooms[key].push(rec);
    }
  }

  const outCols = ['grupo', 'dimensao', 'n', 'media', 'mediana', 'p22', 'p75'];
  const rows = [];

  for (const [dim, g] of Object.entries(groups)) {
    for (const [label, items] of Object.entries(g)) {
      const s = summarize(items, (r) => Number(r.avg_daily_price));
      rows.push({ grupo: label, dimensao: dim, n: s.n, media: s.mean, mediana: s.median, p22: s.p22, p75: s.p75 });
    }
  }

  writeCSV(path.join(OUT_DIR, 'perfil_bairro_resumo.csv'), rows);

  // ---- Ordena para leitura ----
  const topBairro = rows.filter((r) => r.dimensao === 'suburb').sort((a, b) => (b.mediana||0) - (a.mediana||0));
  const topPerfil = rows.filter((r) => r.dimensao === 'n_bedrooms').sort((a, b) => (b.mediana||0) - (a.mediana||0));
  const topTipo = rows.filter((r) => r.dimensao === 'listing_type').sort((a, b) => (b.mediana||0) - (a.mediana||0));

  function print(dimTitle, arr) {
    console.log(`\n=== ${dimTitle} (por mediana de diária) ===`);
    console.log(['grupo','n','media','mediana','p22','p75'].map(h=>h.padEnd(22)).join(''));
    for (const r of arr) {
      console.log([r.grupo, r.n, r.media, r.mediana, r.p22, r.p75].map((v)=>String(v).padEnd(22)).join(''));
    }
  }
  print('BAIRROS', topBairro);
  print('Nº DE QUARTOS', topPerfil);
  print('TIPO DE ANÚNCIO', topTipo);

  fsWriteReport({ join: { total: consolidated.length, inMesh, inDetails, inBoth, lost: consolidated.length - inBoth },
    bairros: topBairro, perfis: topPerfil, tipos: topTipo });
}

function fsWriteReport(obj) {
  const fs = require('fs');
  fs.writeFileSync(path.join(OUT_DIR, 'perfil_bairro_report.json'), JSON.stringify(obj, null, 2), 'utf8');
}

main();

'use strict';

/**
 * Comparação específica: imóveis compactos (1 quarto) no Centro vs outros
 * perfis que aparecem como relevantes.
 *
 * Não assumimos que number_of_bedrooms=0 é "studio" (os anúncios com 0 quartos
 * são heterogêneos: casas, suítes, hostels). Por isso o "compacto" operacional
 * aqui é o imóvel de 1 quarto; incluímos uma linha de referência com
 * 1+0 quartos rotulada claramente como "1 quarto + 0 quartos (sem quarto decl.)".
 *
 * Comparação em duas leituras:
 *   1) Por diária (avg_daily_price) - métrica principal.
 *   2) Por receita anual estimada em 3 cenários de ocupação (40/50/60%) -
 *      sensibilidade.
 */

const path = require('path');
const { readCSV, writeCSV } = require('./lib/csv');

const DATA_DIR = path.join(__dirname, '..', 'data');
const OUT_DIR = path.join(__dirname, 'output');

function percentile(sorted, p) {
  if (!sorted.length) return null;
  const idx = (p / 100) * (sorted.length - 1);
  const lo = Math.floor(idx), hi = Math.ceil(idx);
  if (lo === hi) return sorted[lo];
  return sorted[lo] + (sorted[hi] - sorted[lo]) * (idx - lo);
}

function stats(items, field) {
  const vals = items.map((r) => Number(r[field])).filter((v) => !isNaN(v)).sort((a, b) => a - b);
  const n = items.length;
  const mean = vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
  return { n, mean, median: percentile(vals, 50), p22: percentile(vals, 22), p75: percentile(vals, 75) };
}

function main() {
  const consolidated = readCSV(path.join(OUT_DIR, 'price_consolidated.csv'));
  const mesh = readCSV(path.join(DATA_DIR, 'Mesh_Ids_Data_Itapema.csv'));
  const details = readCSV(path.join(DATA_DIR, 'Details_Itapema.csv'));

  const meshById = new Map(mesh.map((r) => [r.airbnb_listing_id, r]));
  const detailsById = new Map(details.map((r) => [r.airbnb_listing_id, r]));

  const joined = consolidated.map((rec) => {
    const m = meshById.get(rec.airbnb_listing_id);
    const d = detailsById.get(rec.airbnb_listing_id);
    return {
      ...rec,
      suburb: m ? String(m.suburb).trim() : null,
      listing_type: d ? String(d.listing_type).trim() : null,
      n_bedrooms: d ? d.number_of_bedrooms : null,
    };
  }).filter((r) => r.suburb && r.n_bedrooms !== null && r.n_bedrooms !== '');

  // ---- Definição dos grupos de comparação ----
  const groups = {
    'CENTRO - 1 quarto (compacto)': (r) => r.suburb === 'Centro' && r.n_bedrooms === '1',
    'CENTRO - 1+0 quartos (compacto ampliado)': (r) => r.suburb === 'Centro' && (r.n_bedrooms === '1' || r.n_bedrooms === '0'),
    'CENTRO - 2 quartos': (r) => r.suburb === 'Centro' && r.n_bedrooms === '2',
    'CENTRO - 3 quartos': (r) => r.suburb === 'Centro' && r.n_bedrooms === '3',
    'MEIA PRAIA - 1 quarto (compacto)': (r) => r.suburb === 'Meia Praia' && r.n_bedrooms === '1',
    'MEIA PRAIA - 2 quartos': (r) => r.suburb === 'Meia Praia' && r.n_bedrooms === '2',
    'MEIA PRAIA - 3 quartos': (r) => r.suburb === 'Meia Praia' && r.n_bedrooms === '3',
    'MORRETES - 1 quarto (compacto)': (r) => r.suburb === 'Morretes' && r.n_bedrooms === '1',
    'MORRETES - 2 quartos': (r) => r.suburb === 'Morretes' && r.n_bedrooms === '2',
    'MORRETES - 3 quartos': (r) => r.suburb === 'Morretes' && r.n_bedrooms === '3',
  };

  const rows = [];
  for (const [label, fn] of Object.entries(groups)) {
    const items = joined.filter(fn);
    const daily = stats(items, 'avg_daily_price');
    const row = {
      grupo: label,
      n: daily.n,
      media: daily.mean,
      mediana: daily.median,
      p22: daily.p22,
      p75: daily.p75,
      'receita_anual_occ40': stats(items, 'annual_revenue_occ_40').mean,
      'receita_anual_occ50': stats(items, 'annual_revenue_occ_50').mean,
      'receita_anual_occ60': stats(items, 'annual_revenue_occ_60').mean,
    };
    const f = (v) => (v === null || v === undefined ? '' : +Number(v).toFixed(2));
    rows.push({
      grupo: label, n: row.n, media: f(row.media), mediana: f(row.mediana), p22: f(row.p22), p75: f(row.p75),
      'receita_anual_occ40': f(row.receita_anual_occ40),
      'receita_anual_occ50': f(row.receita_anual_occ50),
      'receita_anual_occ60': f(row.receita_anual_occ60),
    });
  }

  writeCSV(path.join(OUT_DIR, 'comparacao_compactos_centro.csv'), rows);

  const sorted = rows.slice().sort((a, b) => (b.mediana||0) - (a.mediana||0));
  console.log(['grupo','n','media','mediana','p22','p75','R50/ano'].map((h) => h.padEnd(34)).join(''));
  for (const r of sorted) {
    console.log([
      r.grupo, r.n, r.media, r.mediana, r.p22, r.p75, r.receita_anual_occ50,
    ].map((v) => String(v).padEnd(34)).join(''));
  }
}

main();

