'use strict';
const path = require('path');
const { readCSV } = require('./lib/csv');
const OUT = path.join(__dirname, 'output');

const ranking = readCSV(path.join(OUT, 'ranking_roi.csv'));
const compact = readCSV(path.join(OUT, 'comparacao_compactos_centro.csv'));

// Map ranking by (bairro, quartos)
const rk = new Map();
for (const r of ranking) rk.set(`${r.bairro}_${r.quartos}`, r);

// Map compact by normalized group label (extract bairro + quartos from label)
const cm = {};
for (const r of compact) {
  const m = /^(CENTRO|MEIA PRAIA|MORRETES) - (\d) quarto/.exec(r.grupo);
  if (m) cm[`${m[1]}_${m[2]}`] = r;
}

const canonBairro = { CENTRO: 'Centro', 'MEIA PRAIA': 'Meia Praia', MORRETES: 'Morretes' };

let allOk = true;
for (const key of Object.keys(cm)) {
  const bairro = canonBairro[key.split('_')[0]];
  const quartos = key.split('_')[1];
  const c = cm[key];
  const r = rk.get(`${bairro}_${quartos}`);
  if (!r) { console.log('SEM CORRESPONDENTE no ranking:', key); allOk = false; continue; }
  const sameN = String(c.n) === String(r.n_airbnb);
  const sameDaily = Math.abs(Number(c.mediana) - Number(r.diaria_mediana)) < 0.01;
  const sameR50 = Math.abs(Number(c.receita_anual_occ50) - Number(r.receita_anual_occ50)) < 1;
  const ok = sameN && sameDaily && sameR50;
  if (!ok) allOk = false;
  console.log(`${ok ? 'OK  ' : 'DIF '} ${key} | n ${c.n} vs ${r.n_airbnb} | diaria ${c.mediana} vs ${r.diaria_mediana} | R50 ${c.receita_anual_occ50} vs ${r.receita_anual_occ50}`);
}
console.log('\nRESULTADO:', allOk ? '100% CONSISTENTE com ranking final' : 'HAVERÁ INCONSISTÊNCIAS');

