'use strict';
const { spawnSync } = require('child_process');
const fs = require('fs');
const path = require('path');

const sessionId = process.argv[2];
const outFile = process.argv[3];
const opencodeBin = process.argv[4] || 'opencode';

const res = spawnSync(opencodeBin, ['export', sessionId], {
  encoding: null, // keep raw bytes
  maxBuffer: 1024 * 1024 * 256,
  env: { ...process.env, OPENCODE_CLI: '1' },
  windowsHide: true,
});

if (res.error) { console.error('spawn error:', res.error.message); process.exit(1); }
if (res.status !== 0) {
  console.error('export failed with status', res.status);
  if (res.stderr && res.stderr.length) console.error('stderr:', res.stderr.toString('utf8').slice(0, 2000));
  process.exit(1);
}

const bytes = res.stdout;
// Basic validation: should start with '{' after optional BOM
const firstByte = bytes[0];
if (firstByte !== 0x7b) {
  // try to detect UTF-16LE BOM (FF FE)
  if (bytes[0] === 0xff && bytes[1] === 0xfe) {
    console.error('WARNING: export produced UTF-16LE output; converting to UTF-8');
    const utf16 = bytes.slice(2).toString('utf16le');
    fs.writeFileSync(outFile, utf16, 'utf8');
  } else {
    console.error('UNEXPECTED first byte:', bytes[0].toString(16));
  }
} else {
  fs.writeFileSync(outFile, bytes); // raw UTF-8 bytes as-is
}

// Validate the written JSON parses
const parsed = JSON.parse(fs.readFileSync(outFile, 'utf8'));
const msgs = Array.isArray(parsed.messages) ? parsed.messages : (parsed.parts || []);
console.log('exported OK ->', outFile);
console.log('bytes:', fs.statSync(outFile).size);
console.log('top-level keys:', Object.keys(parsed).join(', '));
console.log('message parts:', msgs.length);
